INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('39e61c87-b4d3-4054-abcf-aa550afba711', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-01', 1, 'Dividing work means each person finishes a part alone. Learning together means the group talks through every part until all of us understand the whole. Think of a history project where each person writes one section. When the teacher asks about another section, nobody can answer, because nobody discussed it. So group work is truly collaborative when every member can explain the full answer, not just their own piece, in their own words.', '[{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":152},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":158},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":129}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', '04851bca-272d-45a8-a1f0-d1053dcfec86', '2026-11-02T13:53:22.000Z', '2026-11-02T14:04:12.000Z', 1, '2026-11-02T13:53:22.000Z', '2026-11-02T14:04:12.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('fff2b590-f465-4984-a265-5e2358a0cecf', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-01","scenarioOrder":1}', '2026-11-02T13:53:22.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('19044b24-2c1b-454c-ac36-4a91cd1256bb', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 1, 'Splitting is what we did in every group project in school, to be honest.', '2026-11-02T13:54:07.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('c10d8837-bee2-457e-a4eb-7df14e8bf08c', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 1, 'Yes, but then I only knew my part. In the history project I could not answer one question about the other sections.', '2026-11-02T13:54:57.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('37502fce-f844-47c7-a7af-3ae51b7e1582', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 1, 'So the difference is whether we can explain each other''s parts?', '2026-11-02T13:55:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('9802cbdf-703e-4f00-a699-962453042ff2', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 1, 'Lets each get the full answer and compare with what we said.', '2026-11-02T13:56:57.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('5155aa51-3de3-4a6e-a548-4ae8f6d2ba5b', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 1, 'Mine has almost exactly our history example. Feels like it gave us everything.', '2026-11-02T14:00:12.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('da1cd2fe-7561-4ca6-a24e-e880423b2ed7', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 1, 'Lets keep our own example then and write it simply, for a first-year.', '2026-11-02T14:00:47.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('0cf5afbe-5fe5-4d73-afa0-320fb7b729bf', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 1, 'full_answer', 'Dividing work means each member completes a separate piece. Collaborative learning means the group builds understanding together, so every member can explain the whole result. For example, in a history project split into sections, a member who never discussed the other sections cannot answer questions about them.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 1. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1900, 1, 1, 0, '2026-11-02T13:57:32.000Z', '2026-11-02T13:57:36.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('ec812d11-907a-4797-af5d-92c9a83dc90d', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'ai_support_requested', '{"scenarioOrder":1,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":1900}', '2026-11-02T13:57:33.900Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('93ab37bd-b3eb-4aa1-aef3-aa3a56e0dfb4', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 1, 'full_answer', 'Group work is truly collaborative when members think through the task together rather than only assembling separate parts. A simple test is whether each member could explain any part of the final answer. A project where each person writes one section and never reads the others fails that test.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 1. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2100, 1, 1, 0, '2026-11-02T13:57:50.000Z', '2026-11-02T13:57:54.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('d5106e24-e054-4280-aa13-11456653298a', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'ai_support_requested', '{"scenarioOrder":1,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2100}', '2026-11-02T13:57:52.100Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('93c5d8a5-d5bb-471f-a937-8187d78e66a1', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 1, 'full_answer', 'Splitting the assignment finishes the work, but it does not mean the group learned together. In collaborative learning the members discuss, question and connect each other''s parts. For example, a history project split into sections leaves each student unable to explain the sections they did not write.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 1. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1800, 1, 1, 0, '2026-11-02T13:58:22.000Z', '2026-11-02T13:58:26.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('955c3578-582a-4184-a336-e3069a17c6f1', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'ai_support_requested', '{"scenarioOrder":1,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":1800}', '2026-11-02T13:58:23.800Z');
