INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('646fba4b-2624-4126-a794-402208944d78', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-02', 2, 'The answer is incomplete because speed is only one benefit. It misses that we learn from hearing how the others think and from explaining our own ideas. Splitting can even reduce learning when the parts depend on each other, like a lab report where the method and the results are written by different people who never compare. Revised answer: group work is useful when members discuss, question and are accountable for the whole result, not only when it is faster.', '[{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":153},{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":174},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":137}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'da299bbc-3884-487b-ae94-705cedb40326', '2026-11-02T14:07:22.000Z', '2026-11-02T14:17:32.000Z', 1, '2026-11-02T14:07:22.000Z', '2026-11-02T14:17:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('c3c10483-e9c2-45ce-ab08-9e1db0920534', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-02","scenarioOrder":2}', '2026-11-02T14:07:22.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('e5236943-1421-4b5a-a232-76d66eecd445', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 2, 'Faster is true, but it is not the point of group work.', '2026-11-02T14:08:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('3abe8f31-291a-410f-acb7-35d9b9523362', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 2, 'Missing: you learn from hearing how the others think.', '2026-11-02T14:09:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('da711a64-dd1d-4fa4-aca1-cfdea6d9f93d', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 2, 'And splitting reduces learning when the parts depend on each other, like a lab report.', '2026-11-02T14:10:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('28ac63c1-498f-4ba8-a0cb-4eea5768298d', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 2, 'It lists what we had plus accountability. Lets add that one.', '2026-11-02T14:13:52.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('cb4989b9-e362-488f-afad-3e08ec905109', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 2, 'full_answer', 'The answer is incomplete because it treats speed as the main benefit. Collaborative learning also involves learning from others'' reasoning, explaining your own ideas and shared accountability for the result. Splitting can reduce learning when the parts depend on each other and are never compared.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 2. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2000, 1, 1, 0, '2026-11-02T14:10:47.000Z', '2026-11-02T14:10:51.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('4aab2db4-c37c-475c-a003-1bafc36376e1', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'ai_support_requested', '{"scenarioOrder":2,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2000}', '2026-11-02T14:10:49.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('2be0f380-f4cc-439e-a571-8bf01be8804b', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 2, 'full_answer', 'Speed is one possible benefit, but the answer misses the main ones: hearing different reasoning, having to explain ideas, and being accountable for the whole result. When parts depend on each other, such as method and results in a lab report, splitting without discussion lowers learning.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 2. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1700, 1, 1, 0, '2026-11-02T14:11:02.000Z', '2026-11-02T14:11:06.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('eb5f9378-b448-499a-a93d-ba5c0b851e1e', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'ai_support_requested', '{"scenarioOrder":2,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":1700}', '2026-11-02T14:11:03.700Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('092c598a-4c60-4a24-aa8d-63cdc31e9a6f', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 2, 'full_answer', 'The statement is misleading because it values finishing over learning. A better answer would mention discussion, explanation and joint responsibility. Splitting reduces learning when members never check how their parts connect.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 2. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1900, 1, 1, 0, '2026-11-02T14:11:32.000Z', '2026-11-02T14:11:36.000Z');
