INSERT INTO surveys ("id", "session_id", "participant_id", "scenario_id", "perceived_helpfulness", "support_amount", "ai_helped_discussion", "ai_helped_focus", "ai_helped_inclusion", "ai_helped_disagreement", "collaboration_rating", "shared_answer_rating", "autonomy_rating", "ai_helped_thinking", "over_reliance_rating", "could_answer_without_ai", "satisfaction_rating", "open_reflection", "answer_confidence", "confidence_reason", "do_differently", "created_at") VALUES ('3575f8f5-bbe2-4542-a0c0-831fd4801f57', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'scenario-02', 4, 'appropriate', 3, 4, 3, NULL, 4, 5, 2, 3, 4, 2, 4, 'It helped me understand, but I would not say it like this.', 2, 'I agree with it, but I am not sure I could defend every sentence.', 'Say my idea before reading the AI answer.', '2026-11-02T14:20:02.000Z');
