INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('34f7370f-cdc4-4f85-aa32-75e223932516', '646fba4b-2624-4126-a794-402208944d78', 'final', 'P. Palat', 3, 3, 3, 3, 3, 2, '17/24. Correct and shared, own example included, but structure follows the full AI answer closely.', '2026-11-03T16:17:32.000Z', '2026-11-03T16:17:32.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('10098b82-3d00-412c-a391-63ce7c2a65c2', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-03', 3, 'We recommend assigned roles. The student who does almost nothing gets a clear task, and the presenter or recorder cannot stay invisible. Roles alone do not stop the student who takes over, so the facilitator should rotate and the critic should question decisions before they are final. Peer assessment is fairer for grading but can turn into a popularity vote, and the quiz only shows learning after the project. Our assumption is that the teacher checks the roles are followed.', '[{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":137},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":149},{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":192}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'da299bbc-3884-487b-ae94-705cedb40326', '2026-11-02T14:20:42.000Z', '2026-11-02T14:32:52.000Z', 1, '2026-11-02T14:20:42.000Z', '2026-11-02T14:32:52.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('810538d7-f33f-4793-a396-e81ce6c479fc', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-03","scenarioOrder":3}', '2026-11-02T14:20:42.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('d63b54e5-0a48-426d-aab7-467a0469aa91', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 3, 'Three options. Peer assessment, roles, or a quiz.', '2026-11-02T14:21:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('f6182ab1-b904-4ce8-abbc-9b61738d839c', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 3, 'Roles would force the quiet one to do something. The presenter cant hide.', '2026-11-02T14:22:42.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('cd7455fb-4306-458f-a095-7f3ebb8a5f6d', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 3, 'But roles do not stop the one who takes over. The facilitator can still decide everything.', '2026-11-02T14:23:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('3e5346bb-1dfe-4ae9-a21b-96dec7881ca5', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 3, 'The quiz checks if everyone learned, but it comes too late to fix the project.', '2026-11-02T14:24:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('31904a8b-edd7-4768-a5fb-cf1de9dead6e', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 3, 'This is too revealing, it picks the option and gives the risk too. We had roles, lets not just switch to its choice.', '2026-11-02T14:28:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('ab38fc4e-1cbb-4b26-ad9d-ff4a9431c172', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 3, 'Ok, but its point about rotating the facilitator is fair. We say it in our words.', '2026-11-02T14:29:12.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('c963985d-3fb6-4226-a012-23d50a359719', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 3, 'full_answer', 'Recommend assigned roles, with the facilitator role rotating. Roles give the inactive student a visible responsibility, while rotation and a critic role limit the dominant student. Peer assessment is fairer for grading but risks becoming a popularity vote, and a quiz checks learning only after the project.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 3. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2200, 1, 1, 0, '2026-11-02T14:25:32.000Z', '2026-11-02T14:25:36.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('f0631c0e-eee5-4293-a7bf-e7fbea2b2df9', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'ai_support_requested', '{"scenarioOrder":3,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2200}', '2026-11-02T14:25:34.200Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('f1916631-f66a-4b47-a5fc-8bfa9b9a1ac1', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 3, 'full_answer', 'Assigned roles are the strongest option if the facilitator rotates. The inactive student gets a clear task, and the critic can challenge decisions made by one person. Peer assessment helps fairness but can be biased by friendships. A quiz measures learning but does not change participation during the project.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 3. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2000, 1, 1, 0, '2026-11-02T14:25:42.000Z', '2026-11-02T14:25:46.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('2760e19f-d77e-491d-abf6-c717e41e8b65', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'ai_support_requested', '{"scenarioOrder":3,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2000}', '2026-11-02T14:25:44.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('e807b797-5265-4eae-ac3c-4b3d56b6faad', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 3, 'full_answer', 'Choose roles. They address both problems: the quiet member must contribute and the dominant member shares decisions if the facilitator rotates. Peer assessment may harm students with fewer friends in the group, and the quiz comes too late. The assumption is that the teacher checks that roles are followed.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 3. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 2300, 1, 1, 0, '2026-11-02T14:26:12.000Z', '2026-11-02T14:26:16.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('c95bd98f-2e7b-40de-a9b3-20302db05da7', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'ai_support_requested', '{"scenarioOrder":3,"scaffoldingType":"full_answer","mocked":false,"model":"gpt-6-luna","latencyMs":2300}', '2026-11-02T14:26:14.300Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('0cc1e9e3-bcb1-4299-a2d0-09d2954c7769', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 3, 'finalAnswer', 137, 12, 'We recommend assigned roles. The student who does almost nothing gets a clear task, and the presenter or recorder cannot stay invisible.', '2026-11-02T14:27:27.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('5fa4cecd-c4bc-4855-a63d-9afa0866948b', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 3, 'finalAnswer', 149, 0, 'Roles alone do not stop the student who takes over, so the facilitator should rotate and the critic should question decisions before they are final.', '2026-11-02T14:28:12.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('5cacfad1-c8fa-4036-a7b7-ae56a926021c', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 3, 'finalAnswer', 192, 0, 'Peer assessment is fairer for grading but can turn into a popularity vote, and the quiz only shows learning after the project. Our assumption is that the teacher checks the roles are followed.', '2026-11-02T14:28:57.000Z');
