INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('edf520f7-fc73-45b3-ae32-77279b6f59ee', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-04', 4, 'It is not acceptable to submit a full AI answer the group has not read. The grade would show the AI''s work, not ours, and it is unfair if one member decides for everyone. Time pressure explains the temptation, but it does not justify it. A full AI answer could be used only to compare after we wrote our own position. If there is really no time, the honest option is to ask the teacher for an extension or to submit a shorter answer we understand.', '[{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":171},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":147},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":129}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', '04851bca-272d-45a8-a1f0-d1053dcfec86', '2026-11-02T14:36:02.000Z', '2026-11-02T14:47:42.000Z', 1, '2026-11-02T14:36:02.000Z', '2026-11-02T14:47:42.000Z');
