INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('65ab2016-1bd6-4c3a-a07f-5a1d50e9def6', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 4, 'The full answer says only for comparison after our own reasoning. Same as we said.', '2026-11-02T14:41:32.000Z');
