INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('6c594895-6486-49fb-a8b4-59f2a7b73b32', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 4, 'full_answer', 'Submitting a full AI answer that the group has not read is not acceptable. It misrepresents the group''s learning and is unfair to members who were not asked. Time pressure explains the temptation but does not justify it. A full AI answer can be justified only as a comparison after the group has formed its own position.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 4. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1800, 1, 1, 0, '2026-11-02T14:39:12.000Z', '2026-11-02T14:39:16.000Z');
