INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('bae5d53e-f096-4215-a90b-698d415c3235', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 4, 'finalAnswer', 129, 0, 'If there is really no time, the honest option is to ask the teacher for an extension or to submit a shorter answer we understand.', '2026-11-02T14:42:37.000Z');
