INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('228b3d04-e62d-487b-a3b5-85c97fc5dfca', 'edf520f7-fc73-45b3-ae32-77279b6f59ee', 'final', 'P. Palat', 3, 3, 3, 3, 2, 3, '17/24. Correct and shared, own example included, but structure follows the full AI answer closely.', '2026-11-03T16:47:42.000Z', '2026-11-03T16:47:42.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('7f245e1c-2a47-4ece-aaa6-9ac2a179d192', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-05', 5, 'SRL happens when one student notices they do not understand a source, plans to reread it and checks whether their understanding improved. CoRL happens when a teammate asks that student to explain the source and points out a missed assumption, helping the student correct their approach. SSRL happens when all three set a shared goal, monitor whether the assignment is on track and change their plan together. These processes support personal responsibility, peer help and coordinated group progress.', '[{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":138},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":149},{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":212}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', '2026-11-02T14:50:52.000Z', '2026-11-02T15:01:42.000Z', 1, '2026-11-02T14:50:52.000Z', '2026-11-02T15:01:42.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('490bff0d-2f70-45e7-acb4-b740497a3f59', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-05","scenarioOrder":5}', '2026-11-02T14:50:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('74733f89-46a8-4af7-ab12-f26aed571e84', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 5, 'No full answers from now. We saw it decides for us.', '2026-11-02T14:51:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('cf9980f1-6bf8-45c2-a89e-6415c14ddc04', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 5, 'SRL is one student managing their own learning. CoRL is help from another student.', '2026-11-02T14:52:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('9116feeb-78c0-4acf-a5e2-cb7776265109', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 5, 'SSRL is all three of us checking the group plan. We need a clear example for each.', '2026-11-02T14:53:37.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('8f7737ab-273f-41cb-a6bb-f07475631371', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 5, 'Lets use one difficult research assignment for all three examples.', '2026-11-02T14:54:42.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('06feabe3-426d-4472-aba4-826e22b9c05e', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 5, 'The explanation confirms that the difference is who controls the regulation.', '2026-11-02T14:58:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('b181aaaf-0133-4a14-a7c2-b25e91ee2cc9', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 5, 'Feedback says connect each example to successful collaboration. Adding that.', '2026-11-02T14:58:42.000Z');
INSERT INTO individual_scaffolds ("id", "session_id", "participant_id", "scenario_order", "scaffolding_type", "ai_response", "ai_prompt_system", "ai_prompt_user", "ai_model", "ai_latency_ms", "selected", "times_selected", "times_unselected", "created_at", "last_toggled_at") VALUES ('a2b357e0-895b-4261-ab63-507b1d323371', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 5, 'explanation', 'Distinguish the processes by who regulates learning: the individual in SRL, one person supporting another in CoRL, and the group collectively in SSRL. They can all occur during the same assignment.', 'Learning support for one student in a research study. Scaffold the group; do not take over the task.', 'Scenario 5. Group discussion so far and the answer written so far were included.', 'gpt-6-luna', 1300, 1, 1, 0, '2026-11-02T14:55:22.000Z', '2026-11-02T14:55:26.000Z');
