INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('ea818f09-9c7b-46f3-ad30-d64314f1f4a4', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-06', 6, 'Contributing more messages or text does not necessarily mean participating more meaningfully. A quiet member may ask one question that reveals a mistaken assumption. A valuable contribution moves the group''s understanding forward by explaining a reason, connecting ideas, challenging a claim or inviting another member to clarify. Members help one another by listening, asking follow-up questions, giving constructive feedback and checking that everyone can explain the shared answer, even when their visible contributions are unequal.', '[{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":166},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":165},{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":204}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'da299bbc-3884-487b-ae94-705cedb40326', '2026-11-02T15:04:52.000Z', '2026-11-02T15:15:02.000Z', 1, '2026-11-02T15:04:52.000Z', '2026-11-02T15:15:02.000Z');
