INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('7483e1e6-61e1-4255-ad46-9ec4b02f9080', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 6, 'More messages cannot automatically mean better participation.', '2026-11-02T15:05:37.000Z');
