INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('db98b6d1-5ae0-4c9d-ab61-f965b51ce482', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 6, 'I will ask for feedback on our reasoning. Only feedback, we know the rest.', '2026-11-02T15:08:52.000Z');
