INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('51c18053-f0e3-4146-a88b-98b729bce84a', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-07', 7, 'We would restrict AI in group projects. A ban cannot be enforced, and unrestricted use lets a group submit a report no member engaged with. The line between support and substitution is whether the group can show its own thinking: a draft history and a short oral check where any member explains the report. AI may be used for questions, hints and feedback, but each member''s contribution should still be visible, so the grade stays fair.', '[{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":140},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":167},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":130}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'da299bbc-3884-487b-ae94-705cedb40326', '2026-11-02T15:18:12.000Z', '2026-11-02T15:29:22.000Z', 1, '2026-11-02T15:18:12.000Z', '2026-11-02T15:29:22.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('58cac539-2320-4c8f-a8af-fae38251d9e1', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-07","scenarioOrder":7}', '2026-11-02T15:18:12.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('a715f437-3b2f-447c-a890-8f6588da9698', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 7, 'Ban is impossible to check. People will use it at home.', '2026-11-02T15:18:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('ee2b8239-24e0-46b9-a3e0-178608069335', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 7, 'Unrestricted means some groups never read their own report.', '2026-11-02T15:19:52.000Z');
