INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('21ae5c5b-fec6-4fdd-a3d9-0ebc9b852de2', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 7, 'finalAnswer', 140, 12, 'We would restrict AI in group projects. A ban cannot be enforced, and unrestricted use lets a group submit a report no member engaged with.', '2026-11-02T15:24:17.000Z');
