INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('debd97a9-17de-41ac-aca3-56645773ba24', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 7, 'finalAnswer', 130, 0, 'AI may be used for questions, hints and feedback, but each member''s contribution should still be visible, so the grade stays fair.', '2026-11-02T15:25:47.000Z');
