INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('810e12c4-e9b8-4110-a7d1-e80be5b771f4', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'survey_submitted', '{"scenarioId":"scenario-08","answerConfidence":3}', '2026-11-02T15:45:52.000Z');
INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('9624f769-14f1-43ae-adfe-01a366225248', '2d5239dc-f555-4b1a-af5a-abe8d0f1bb58', 'final', 'P. Palat', 3, 3, 3, 2, 2, 3, '16/24. Good interpretation of causation; additional data only partly specified. Two contributors.', '2026-11-03T17:43:22.000Z', '2026-11-03T17:43:22.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('52a99efc-fe0b-41ba-a15b-f4feadc7f168', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-09', 9, 'No. Exactly one topic each is not always fair because topics vary in difficulty and members have different time and experience. Everyone first writes down availability and strengths. Each member then picks two preferred topics. If two people want the same topic, we compare who has the lighter workload so far. To stay fair, the hardest topic rotates between presentations, and we have a short check-in halfway to see if anyone needs help or the workload changed.', '[{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":183},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":128},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":152}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', '04851bca-272d-45a8-a1f0-d1053dcfec86', '2026-11-02T15:46:32.000Z', '2026-11-02T15:56:42.000Z', 1, '2026-11-02T15:46:32.000Z', '2026-11-02T15:56:42.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('830da4ed-c2b3-49a3-a133-488849c853e2', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-09","scenarioOrder":9}', '2026-11-02T15:46:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('d7cb1ee1-e8d2-48ac-ac2a-f2ecf3e43c54', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 9, 'Four members, different strengths and schedules.', '2026-11-02T15:47:12.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('76d51ff6-c983-4e65-a5c2-ba559774ce9e', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 9, 'First everyone writes availability and which topics they are good at.', '2026-11-02T15:48:07.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('473f660b-d5ea-4b33-a609-839624bfb2be', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 9, 'Then everyone picks two topics, and if two people want the same, we compare workload.', '2026-11-02T15:49:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('4d820cc6-c1af-48ea-a89e-0033defe88c5', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 9, 'What if someone always ends up with the hardest topic?', '2026-11-02T15:50:02.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('61277cd9-7414-4fa3-ac7d-745000213e59', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 9, 'Then it rotates. And a check-in halfway, in case the workload changes. I think we dont need AI here.', '2026-11-02T15:50:52.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('3129de6e-ff15-4162-a9f3-fb609162c627', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 9, 'finalAnswer', 183, 12, 'No. Exactly one topic each is not always fair because topics vary in difficulty and members have different time and experience. Everyone first writes down availability and strengths.', '2026-11-02T15:48:27.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('a43a6825-1c0c-4a06-a4fa-10486d0d2b6a', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 9, 'finalAnswer', 128, 0, 'Each member then picks two preferred topics. If two people want the same topic, we compare who has the lighter workload so far.', '2026-11-02T15:49:12.000Z');
INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('8b8810ce-7b7c-4c27-a9c1-9e92c21f1998', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 9, 'finalAnswer', 152, 0, 'To stay fair, the hardest topic rotates between presentations, and we have a short check-in halfway to see if anyone needs help or the workload changed.', '2026-11-02T15:49:57.000Z');
