INSERT INTO surveys ("id", "session_id", "participant_id", "scenario_id", "perceived_helpfulness", "support_amount", "ai_helped_discussion", "ai_helped_focus", "ai_helped_inclusion", "ai_helped_disagreement", "collaboration_rating", "shared_answer_rating", "autonomy_rating", "ai_helped_thinking", "over_reliance_rating", "could_answer_without_ai", "satisfaction_rating", "open_reflection", "answer_confidence", "confidence_reason", "do_differently", "created_at") VALUES ('a18e3014-e786-492d-a4cf-8ccd7259576d', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'scenario-09', NULL, NULL, NULL, NULL, NULL, NULL, 5, 5, 5, NULL, NULL, NULL, 5, 'We talked it through and did not get stuck.', 5, 'I can explain my part and the others'' parts.', 'Write a bigger part myself.', '2026-11-02T15:59:12.000Z');
