INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('7d19e33c-154b-44bd-a625-c6b2f2983f46', '52a99efc-fe0b-41ba-a15b-f4feadc7f168', 'final', 'P. Palat', 4, 3, 3, 3, 3, 3, '19/24. Group''s own reasoning, no AI. Clear and complete.', '2026-11-03T17:56:42.000Z', '2026-11-03T17:56:42.000Z');
INSERT INTO scenario_attempts ("id", "session_id", "scenario_id", "scenario_order", "final_answer", "final_answer_authorship", "ready_participant_ids", "submitted_by", "discussion_started_at", "final_answer_at", "submitted", "created_at", "updated_at") VALUES ('a5b4a7a9-d071-4d30-a20f-89637aa6d8ed', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'scenario-10', 10, 'No. Groups should not always follow AI suggestions because the AI may be wrong or may replace their reasoning. A good practice is to request hints or questions after the group has a draft and verify the response before using it. They should avoid letting groups ask for a full AI answer before discussing. In our first tasks the full answer arrived first and the discussion became editing its text. It also makes quieter members stop talking, because the AI answer already sounds better than their own idea.', '[{"participantId":"e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","length":229},{"participantId":"04851bca-272d-45a8-a1f0-d1053dcfec86","length":170},{"participantId":"da299bbc-3884-487b-ae94-705cedb40326","length":108}]', '["e78b80ea-cf09-45b1-a8ac-c1083ae7aa99","04851bca-272d-45a8-a1f0-d1053dcfec86","da299bbc-3884-487b-ae94-705cedb40326"]', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', '2026-11-02T15:59:52.000Z', '2026-11-02T16:09:22.000Z', 1, '2026-11-02T15:59:52.000Z', '2026-11-02T16:09:22.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('b144a746-7217-4b18-a5a9-87020da572fe', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'scenario_started', '{"scenarioId":"scenario-10","scenarioOrder":10}', '2026-11-02T15:59:52.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('eec2235f-0d82-4a03-a9be-712f3364ac80', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 10, 'Last one. We dont need AI for this, we lived it.', '2026-11-02T16:00:32.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('64a296fb-0c14-4d20-ad23-d412cfb07766', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 10, 'Encourage: hints or questions after the group has its own draft.', '2026-11-02T16:01:22.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('51170858-b415-4323-a14b-a74ea6b6ab86', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 10, 'Avoid: asking for the full answer before discussing. Our first tasks were like that.', '2026-11-02T16:02:22.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('4580d1c2-3120-4af9-a801-6fba8afb5755', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 10, 'It also made me quiet at the start. The AI answer was already better than what I would say.', '2026-11-02T16:03:22.000Z');
INSERT INTO discussion_messages ("id", "session_id", "participant_id", "scenario_order", "text", "created_at") VALUES ('cc77e61d-f54c-4eb5-ac22-bfbdb113673f', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 10, 'Good point, put that in as the reason.', '2026-11-02T16:04:17.000Z');
