INSERT INTO edit_events ("id", "session_id", "participant_id", "scenario_order", "field", "chars_added", "chars_removed", "inserted_text", "created_at") VALUES ('4ef6b534-ea89-4dd2-ac31-f74badf5bc5e', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 10, 'finalAnswer', 170, 0, 'They should avoid letting groups ask for a full AI answer before discussing. In our first tasks the full answer arrived first and the discussion became editing its text.', '2026-11-02T16:02:32.000Z');
