INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('bfdd8503-95ab-4554-a244-a8bc12b8a7c7', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'survey_submitted', '{"scenarioId":"scenario-10","answerConfidence":5}', '2026-11-02T16:10:12.000Z');
INSERT INTO surveys ("id", "session_id", "participant_id", "scenario_id", "perceived_helpfulness", "support_amount", "ai_helped_discussion", "ai_helped_focus", "ai_helped_inclusion", "ai_helped_disagreement", "collaboration_rating", "shared_answer_rating", "autonomy_rating", "ai_helped_thinking", "over_reliance_rating", "could_answer_without_ai", "satisfaction_rating", "open_reflection", "answer_confidence", "confidence_reason", "do_differently", "created_at") VALUES ('5738b745-48c9-4dbf-a7ad-ee596257b937', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'scenario-10', NULL, NULL, NULL, NULL, NULL, NULL, 5, 5, 5, NULL, NULL, NULL, 5, 'No AI needed, we knew what we wanted to say.', 5, 'We argued about it and the answer reflects that.', 'Work like this from the first task.', '2026-11-02T16:11:02.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('1d7cf015-38d6-4511-acfb-365e4dfba941', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'survey_submitted', '{"scenarioId":"scenario-10","answerConfidence":5}', '2026-11-02T16:11:02.000Z');
INSERT INTO surveys ("id", "session_id", "participant_id", "scenario_id", "perceived_helpfulness", "support_amount", "ai_helped_discussion", "ai_helped_focus", "ai_helped_inclusion", "ai_helped_disagreement", "collaboration_rating", "shared_answer_rating", "autonomy_rating", "ai_helped_thinking", "over_reliance_rating", "could_answer_without_ai", "satisfaction_rating", "open_reflection", "answer_confidence", "confidence_reason", "do_differently", "created_at") VALUES ('9d76f328-6cb3-4361-a771-4132e8d7c712', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'scenario-10', NULL, NULL, NULL, NULL, NULL, NULL, 5, 5, 5, NULL, NULL, NULL, 5, 'Without AI I said more than in the first tasks.', 5, 'I can explain my part and the others'' parts.', 'Speak earlier in the first tasks.', '2026-11-02T16:11:52.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('3715b7f1-a8e8-4c54-a4c9-69d70f3e3b98', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'survey_submitted', '{"scenarioId":"scenario-10","answerConfidence":5}', '2026-11-02T16:11:52.000Z');
INSERT INTO rubric_scores ("id", "attempt_id", "answer_type", "rater", "correctness", "clarity", "reasoning", "completeness", "use_of_examples", "depth", "notes", "created_at", "updated_at") VALUES ('663bdd5b-b9a9-4307-a016-f3b0a0d3c7c8', 'a5b4a7a9-d071-4d30-a20f-89637aa6d8ed', 'final', 'P. Palat', 4, 4, 3, 3, 3, 4, '21/24. Group''s own reasoning, no AI. Clear and complete.', '2026-11-03T18:09:22.000Z', '2026-11-03T18:09:22.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('ccddf1f1-5cbd-4d63-a938-5cbef65543fa', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":1,"post-5":2,"post-6":0,"post-7":2,"post-8":3}', '{"open_collaboration":"Members depend on each other and build one answer that everyone can explain, instead of joining separate parts.","open_ai_role":"AI should give hints, questions or feedback so the group still does the thinking, and less help as we understand more."}', 7, 8, '2026-11-02T16:17:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('88bed8ae-91e5-4e44-a74f-84b0339c6771', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'assessment_completed', '{"assessmentType":"post","score":7,"maxScore":8}', '2026-11-02T16:17:32.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('0738949e-c597-4748-afd3-d474d17b544b', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', '{"ai_effect_on_collaboration":"On the first tasks it shortened the discussion, because we compared our ideas with the full answer instead of with each other. Later it was a small push and we talked more.","most_useful_support":"The guiding question on the data task, and the question Papouris got on the policy task.","unhelpful_or_too_much":"The full answer on the case study. It chose the option and even listed the risks, so there was nothing left to decide.","thinking_and_reliance":"On tasks 1 to 4 partly. After that we did the thinking and used AI only to check.","ai_into_group_answer":"Early on a few phrases. Later I only told the others the idea in the chat.","private_vs_shared_ai":"Private. Each of us had to explain what our AI said, which made us talk.","participation":"Yes, all three of us wrote in almost every answer. On the data task Papouris did not write but helped in the chat.","agreement_on_answer":"Yes on most. On the case study I agreed with roles, but I was not sure we were not just following the AI.","learned_most":"Splitting work and learning together are different, and less AI help gave us better discussions.","suggested_changes":"Maybe ask the group to write a first draft before the full answer can be opened."}', '2026-11-02T16:22:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('fb3a41cf-6512-4623-a8b9-d2c8f5f69af5', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'e78b80ea-cf09-45b1-a8ac-c1083ae7aa99', 'final_reflection_submitted', 'null', '2026-11-02T16:22:32.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('0641f24c-0004-43ef-a527-fa6f9424be44', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'post', '{"post-1":2,"post-2":0,"post-3":1,"post-4":1,"post-5":2,"post-6":0,"post-7":1,"post-8":0}', '{"open_collaboration":"It is collaborative when we discuss and question each other''s ideas and all of us are responsible for the result.","open_ai_role":"Use it after we have our own idea, to check or get unstuck, not to write the answer."}', 6, 8, '2026-11-02T16:19:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('68c639fc-57ea-449d-a1c5-b484bebe7b33', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'assessment_completed', '{"assessmentType":"post","score":6,"maxScore":8}', '2026-11-02T16:19:32.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('48fbae88-3941-41cc-a958-56630c698731', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', '{"ai_effect_on_collaboration":"When everyone opened the full answer we mostly edited its text. When we used hints we argued more.","most_useful_support":"The hint on the data task. It told me where to look but not the answer.","unhelpful_or_too_much":"The full answer on the first task. It already had our history example in it.","thinking_and_reliance":"At the start yes, a bit. From task 5 no.","ai_into_group_answer":"On the second task I used some of its wording about accountability.","private_vs_shared_ai":"Private is better. If it was shared we would just copy one answer.","participation":"Yes. I wrote something in every task, sometimes the longest part.","agreement_on_answer":"Mostly yes. I clicked I am good when I could explain it.","learned_most":"A 12% better score does not prove group work caused it. You have to ask who joined the groups.","suggested_changes":"Show the levels of help with an example, so we know what we get before we choose."}', '2026-11-02T16:23:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('188a1d1f-bb14-4231-a60e-58fbb2627616', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', '04851bca-272d-45a8-a1f0-d1053dcfec86', 'final_reflection_submitted', 'null', '2026-11-02T16:23:32.000Z');
INSERT INTO assessments ("id", "session_id", "participant_id", "assessment_type", "answers", "open_answers", "score", "max_score", "completed_at") VALUES ('5373b14f-aeb8-4696-a167-9af114223091', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'post', '{"post-1":2,"post-2":0,"post-3":3,"post-4":0,"post-5":2,"post-6":0,"post-7":1,"post-8":3}', '{"open_collaboration":"Everyone can explain the whole answer, not only their part, because we talked it through together.","open_ai_role":"Small help like a question is better. A full answer stops the discussion."}', 7, 8, '2026-11-02T16:16:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('c9d36e3d-40de-4cda-a4b5-97015c69b287', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'assessment_completed', '{"assessmentType":"post","score":7,"maxScore":8}', '2026-11-02T16:16:32.000Z');
INSERT INTO final_reflections ("id", "session_id", "participant_id", "answers", "created_at") VALUES ('0f564c00-8f35-473c-a6aa-01ba9aa07e77', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', '{"ai_effect_on_collaboration":"At the start I was quiet, because the full answer already sounded better than my idea. On the later tasks I spoke more.","most_useful_support":"Feedback on our draft in task 4. I chose it instead of the full answer and it was enough.","unhelpful_or_too_much":"The full answer on the first and third tasks was too much.","thinking_and_reliance":"On the first three tasks I relied on it. Not after.","ai_into_group_answer":"Not really. I wrote my parts myself, sometimes after reading the AI.","private_vs_shared_ai":"Private, but then we must say in the chat what it told us.","participation":"I wrote in most answers. In the data task I only discussed, because I did not know what data to ask for.","agreement_on_answer":"On the last tasks fully. On the first ones I agreed because the AI said the same.","learned_most":"Less help can be better, and quiet members speak more when the AI does not answer first.","suggested_changes":"Nothing big. Maybe a reminder that the full answer is for comparison only."}', '2026-11-02T16:22:32.000Z');
INSERT INTO research_events ("id", "session_id", "participant_id", "event_type", "payload", "created_at") VALUES ('836f6692-9c5e-4150-a5f4-2181737b398a', 'f02a5d0f-b95a-46fa-a1bf-206f2e754028', 'da299bbc-3884-487b-ae94-705cedb40326', 'final_reflection_submitted', 'null', '2026-11-02T16:22:32.000Z');
